-- Source: NCA DCC Assessment and Compliance Tool v1.0 (DCC-1:2022).
-- Import all 19 primary and 47 sub-controls as an unassigned reference catalog.
insert into public.frameworks(code,name_ar,name_en,version,description_ar,is_active)
values ('DCC','ضوابط الأمن السيبراني للبيانات','Data Cybersecurity Controls','1-2022','الحد الأدنى من متطلبات الأمن السيبراني لحماية البيانات خلال جميع مراحل دورة حياتها.',true)
on conflict (code) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,version=excluded.version,description_ar=excluded.description_ar,is_active=true;
select setval(pg_get_serial_sequence('public.controls','id'),coalesce((select max(id) from public.controls),0)+1,false);
with source(control_code,title_ar,description_ar,domain_ar,control_type,source_row) as (values
    ('1-1-1', 'المراجعة والتدقيق الدوري للأمن السيبراني - 1-1-1', 'رجوعًا للضابط ١-٨-١ في الضوابط الأساسية للأمن السيبراني، فإنه يجب على الإدارة المعنية بالأمن السيبراني في الجهة مراجعة تطبيق ضوابط الأمن السيبراني للبيانات حسب المدة المحددة لكل مستوى.', 'حوكمة الأمن السيبراني', 'أساسي', 10),
    ('1-1-2', 'المراجعة والتدقيق الدوري للأمن السيبراني - 1-1-2', 'رجوعًا للضابط ١-٨-٢ في الضوابط الأساسية للأمن السيبراني، فإنه يجب أن تتم مراجعة تطبيق ضوابط الأمن السيبراني للبيانات من قبل أطراف مستقلة عن الإدارة المعنية بالأمن السيبراني من داخل الجهة حسب المدة المحددة لكل مستوى.', 'حوكمة الأمن السيبراني', 'أساسي', 11),
    ('1-2-1', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-2-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ١-٩-٣ في الضوابط الأساسية للأمن السيبراني يجب أن تغطي متطلبات الأمن السيبراني المتعلق بالموارد البشرية لتشمل خلال وبعد إنتهاء/إنهاء العلاقة الوظيفية في الجهة بحد أدنى ما يلي:', 'حوكمة الأمن السيبراني', 'أساسي', 12),
    ('1-2-1-1', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-2-1-1', 'إجراء المسح الأمني (Screening and vetting) للعاملين في الوظائف ذات العلاقة بالتعامل مع البيانات.', 'حوكمة الأمن السيبراني', 'فرعي', 13),
    ('1-2-1-2', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-2-1-2', 'تعهد العاملين في الجهة بعدم استخدام تطبيقات التراسل أو التواصل الإجتماعي أو خدمات التخزين السحابية الشخصية لإنشاء أو تخزين أو مشاركة البيانات الخاصة بالجهة، باستثناء تطبيقات التراسل الآمنة المعتمدة من الجهات ذات العلاقة.', 'حوكمة الأمن السيبراني', 'فرعي', 14),
    ('1-3-1', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ١-١٠-٣ في الضوابط الأساسية للأمن السيبراني، فإنه يجب أن يغطي برنامج التوعية بالأمن السيبراني المحاور المتعلقة بحماية البيانات، بما في ذلك:', 'حوكمة الأمن السيبراني', 'أساسي', 15),
    ('1-3-1-1', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1-1', 'مخاطر التسريب والوصول غير المصرح به للبيانات خلال دورة حياتها.', 'حوكمة الأمن السيبراني', 'فرعي', 16),
    ('1-3-1-2', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1-2', 'التعامل الآمن مع البيانات المصنفة خلال السفر والتواجد خارج مكان العمل.', 'حوكمة الأمن السيبراني', 'فرعي', 17),
    ('1-3-1-3', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1-3', 'التعامل الآمن مع البيانات خلال الاجتماعات (الافتراضية والحضورية).', 'حوكمة الأمن السيبراني', 'فرعي', 18),
    ('1-3-1-4', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1-4', 'الاستخدام الآمن للطابعات والماسحات الضوئية وآلات التصوير.', 'حوكمة الأمن السيبراني', 'فرعي', 19),
    ('1-3-1-5', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1-5', 'إجراءات الإتلاف الآمن للبيانات.', 'حوكمة الأمن السيبراني', 'فرعي', 20),
    ('1-3-1-6', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1-6', 'مخاطر مشاركة الوثائق والمعلومات من خلال قنوات تواصل غير مؤمنة.', 'حوكمة الأمن السيبراني', 'فرعي', 21),
    ('1-3-1-7', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1-7', 'المخاطر السيبرانية المتعلقة باستخدام وسائط التخزين الخارجية.', 'حوكمة الأمن السيبراني', 'فرعي', 22),
    ('2-1-1', 'إدارة هويات الدخول والصلاحيات - 2-1-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-٢-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني المتعلقة بإدارة هويات الدخول والصلاحيات، بحد أدنى، ما يلي', 'تعزيز الأمن السيبراني', 'أساسي', 23),
    ('2-1-1-1', 'إدارة هويات الدخول والصلاحيات - 2-1-1-1', 'التقييد الحازم بالسماح للحد الأدنى من العاملين للوصول والاطلاع ومشاركة البيانات بناءً على قوائم صلاحيات مقتصرة على موظفين سعوديين إلا بموجب استثناء من قبل صاحب الصلاحية (رئيس الجهة أو من يفوضه) وعلى أن يتم إعتماد هذه القوائم من قبل صاحب الصلاحية.', 'تعزيز الأمن السيبراني', 'فرعي', 24),
    ('2-1-1-2', 'إدارة هويات الدخول والصلاحيات - 2-1-1-2', 'منع مشاركة قوائم الصلاحيات المعتمدة مع الأشخاص غير المصرح لهم.', 'تعزيز الأمن السيبراني', 'فرعي', 25),
    ('2-1-2', 'إدارة هويات الدخول والصلاحيات - 2-1-2', 'إدارة هويات الدخول وصلاحيات الاطلاع على البيانات باستخدام أنظمة إدارة الصلاحيات الهامة والحساسة (Privileged Access Management).', 'تعزيز الأمن السيبراني', 'أساسي', 26),
    ('2-1-3', 'إدارة هويات الدخول والصلاحيات - 2-1-3', 'بالإضافة للضابط الفرعي ٢-٢-٣-٥ في الضوابط الأساسية للأمن السيبراني، يجب مراجعة قوائم الصلاحيات المعتمدة والصلاحيات المستخدمة للتعامل مع البيانات حسب المدة المحددة لكل مستوى.', 'تعزيز الأمن السيبراني', 'أساسي', 27),
    ('2-2-1', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-2-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-٣-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تشمل متطلبات الأمن السيبراني لحماية الأنظمة وأجهزة معالجة المعلومات، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'أساسي', 28),
    ('2-2-1-1', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-2-1-1', 'تطبيق حزم التحديثات، والإصلاحات الأمنية من وقت إطلاقها للأنظمة المستخدمة للتعامل مع البيانات حسب المدة المحددة لكل مستوى.', 'تعزيز الأمن السيبراني', 'فرعي', 29),
    ('2-2-1-2', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-2-1-2', 'مراجعة إعدادات الحماية والتحصين للأنظمة المستخدمة للتعامل مع البيانات (Security Configuration and Hardening) حسب المدة المحددة لكل مستوى.', 'تعزيز الأمن السيبراني', 'فرعي', 30),
    ('2-2-1-3', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-2-1-3', 'مراجعة وتحصين الإعدادات المصنعية (مثل كلمات المرور الثابتة، والخلفية الافتراضية) للأصول التقنية المستخدمة للتعامل مع البيانات.', 'تعزيز الأمن السيبراني', 'فرعي', 31),
    ('2-2-1-4', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-2-1-4', 'تعطيل خاصية تصوير الشاشة (Print Screen or Screen Capture) للأجهزة التي تنشئ أو تعالج الوثائق.', 'تعزيز الأمن السيبراني', 'فرعي', 32),
    ('2-3-1', 'أمن الأجهزة المحمولة - 2-3-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-٦-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني الخاصة بأمن الأجهزة المحمولة، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'أساسي', 33),
    ('2-3-1-1', 'أمن الأجهزة المحمولة - 2-3-1-1', 'إدارة الأجهزة المحمولة المملوكة للجهة مركزيًا باستخدام نظام إدارة الأجهزة المحمولة (Mobile Device Management – MDM) وتفعيل خاصية الحذف عن بعد.', 'تعزيز الأمن السيبراني', 'فرعي', 34),
    ('2-3-1-2', 'أمن الأجهزة المحمولة - 2-3-1-2', 'إدارة أجهزة (BYOD) مركزيًا باستخدام نظام إدارة الأجهزة المحمولة (Mobile Device Management – MDM) وتفعيل خاصية الحذف عن بعد.', 'تعزيز الأمن السيبراني', 'فرعي', 35),
    ('2-4-1', 'حماية البيانات والمعلومات - 2-4-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-٧-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني الخاصة بحماية البيانات والمعلومات، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'أساسي', 36),
    ('2-4-1-1', 'حماية البيانات والمعلومات - 2-4-1-1', 'استخدام خاصية العلامات المائية لترميز كامل الوثيقة عند الإنشاء والتخزين والطباعة وعلى الشاشة وعلى كل نسخة بحيث يكون الرمز يمكن تتبعه على مستوى المستخدم أو الجهاز.', 'تعزيز الأمن السيبراني', 'فرعي', 37),
    ('2-4-1-2', 'حماية البيانات والمعلومات - 2-4-1-2', 'استخدام تقنيات منع تسريب البيانات (Data Leakage Prevention) وتقنيات إدارة الصلاحيات (Rights Management).', 'تعزيز الأمن السيبراني', 'فرعي', 38),
    ('2-4-1-3', 'حماية البيانات والمعلومات - 2-4-1-3', 'حظر استخدام البيانات في أي بيئة غير بيئة الإنتاج (Production Environment) إلا بعد إجراء تقييم للمخاطر وتطبيق ضوابط لحماية تلك البيانات، مثل تقنيات تعتيم البيانات (Data Masking) أو تقنيات مزج البيانات (Data Scrambling)>', 'تعزيز الأمن السيبراني', 'فرعي', 39),
    ('2-4-1-4', 'حماية البيانات والمعلومات - 2-4-1-4', 'استخدام خدمة حماية العلامة التجارية لحماية هوية الجهة من الانتحال(Brand Protection)', 'تعزيز الأمن السيبراني', 'فرعي', 40),
    ('2-5-1', 'التشفير - 2-5-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-٨-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني للتشفير في الجهة، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'أساسي', 41),
    ('2-5-1-1', 'التشفير - 2-5-1-1', 'استخدام طرق وخوارزميات محدثة وآمنة للتشفير عند الإنشاء والتخزين والمشاركة وعلى كامل الاتصال الشبكي المستخدم لنقل البيانات وفقًا للمستوى المتقدم (Advanced) ضمن المعايير الوطنية للتشــــــفير (NCS – 1:2020).', 'تعزيز الأمن السيبراني', 'فرعي', 42),
    ('2-5-1-2', 'التشفير - 2-5-1-2', 'استخدام طرق وخوارزميات محدثة وآمنة للتشفير عند الإنشاء والتخزين والمشاركة وعلى كامل الاتصال الشبكي المستخدم لنقل البيانات وفقًا للمستوى المتوسط (Moderate) ضمن المعايير الوطنية للتشــــــفير (NCS – 1:2020)', 'تعزيز الأمن السيبراني', 'فرعي', 43),
    ('2-6-1', 'الإتلاف الآمن للبيانات - 2-6-1', 'يجب أن تغطي متطلبات الإتلاف الآمن للبيانات في الجهة بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'أساسي', 44),
    ('2-6-1-1', 'الإتلاف الآمن للبيانات - 2-6-1-1', 'تحديد التقنيات والأدوات والإجراءات لتنفيذ عمليات الإتلاف الآمن للبيانات حسب مستوى تصنيف البيانات.', 'تعزيز الأمن السيبراني', 'فرعي', 45),
    ('2-6-1-2', 'الإتلاف الآمن للبيانات - 2-6-1-2', 'عند انتهاء الحاجة لاستخدام وسائط التخزين بشكل نهائي، يجب أن يتم الإتلاف الآمن (Secure Disposal) لوسائط التخزين وذلك باستخدام التقنيات والأدوات وبإتباع الإجراءات التي تم تحديدها في الضابط رقم ٢-٦-١-١.', 'تعزيز الأمن السيبراني', 'فرعي', 46),
    ('2-6-1-3', 'الإتلاف الآمن للبيانات - 2-6-1-3', 'عند الحاجة لإعادة استخدام وسائط التخزين، يجب أن يتم الحذف الآمن للبيانات (Secure Erasure)، بحيث لا يمكن استرجاعها.', 'تعزيز الأمن السيبراني', 'فرعي', 47),
    ('2-6-1-4', 'الإتلاف الآمن للبيانات - 2-6-1-4', 'يجب أن يتم التحقق من تنفيذ عمليات الإتلاف أو الحذف الآمن للبيانات المشار إليها في الضابطين رقم ٢-٦-١-٢ و٢-٦-١-٣.', 'تعزيز الأمن السيبراني', 'فرعي', 48),
    ('2-6-1-5', 'الإتلاف الآمن للبيانات - 2-6-1-5', 'الاحتفاظ بسجل لعمليات الإتلاف أو الحذف الآمن للبيانات التي تم تنفيذها.', 'تعزيز الأمن السيبراني', 'فرعي', 49),
    ('2-6-2', 'الإتلاف الآمن للبيانات - 2-6-2', 'يجب مراجعة تطبيق متطلبات الإتلاف الآمن للبيانات في الجهة حسب المدة المحددة لكل مستوى.', 'تعزيز الأمن السيبراني', 'أساسي', 50),
    ('2-7-1', 'الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير - 2-7-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لحماية الطابعات والماسحات الضوئية وآلات التصوير في الجهة.', 'تعزيز الأمن السيبراني', 'أساسي', 51),
    ('2-7-2', 'الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير - 2-7-2', 'يجب تطبيق متطلبات الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير في الجهة.', 'تعزيز الأمن السيبراني', 'أساسي', 52),
    ('2-7-3', 'الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير - 2-7-3', 'يجب أن تغطي متطلبات الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'أساسي', 53),
    ('2-7-3-1', 'الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير - 2-7-3-1', 'تعطيل خاصية التخزين المؤقت.', 'تعزيز الأمن السيبراني', 'فرعي', 54),
    ('2-7-3-2', 'الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير - 2-7-3-2', 'تفعيل خاصية التحقق من الهوية في الطابعات والماسحات الضوئية والآت التصوير المركزية قبل بدء عمليات الطباعة والتصوير والمسح الضوئي.', 'تعزيز الأمن السيبراني', 'فرعي', 55),
    ('2-7-3-3', 'الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير - 2-7-3-3', 'الاحتفاظ بطريقة آمنة بسجل الكتروني للعمليات الخاصة باستخدام الطابعات والماسحات الضوئية والآت التصوير، لفترة لا تقل عن 12 شهرًا.', 'تعزيز الأمن السيبراني', 'فرعي', 56),
    ('2-7-3-4', 'الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير - 2-7-3-4', 'تفعيل وحماية سجلات المراقبة لأنظمة CCTV على مواقع أجهزة الطباعة المركزية والماسحات الضوئية والآت التصوير.', 'تعزيز الأمن السيبراني', 'فرعي', 57),
    ('2-7-3-5', 'الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير - 2-7-3-5', 'استخدام أجهزة تمزيق الوثائق الورقية (Cross Shredding)، لإتلاف الوثائق في حال الانتهاء من استخدامها نهائيًا.', 'تعزيز الأمن السيبراني', 'فرعي', 58),
    ('2-7-4', 'الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير - 2-7-4', 'يجب مراجعة تطبيق متطلبات الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير في الجهة حسب المدة المحددة لكل مستوى.', 'تعزيز الأمن السيبراني', 'أساسي', 59),
    ('3-1-1', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 3-1-1', 'بالإضافة للضوابط ضمن المكون الفرعي ٤-١ في الضوابط الأساسية للأمن السيبراني، يجب أن تشمل متطلبات الأمن السيبراني المتعلقة بالأطراف الخارجية، بحد أدنى، ما يلي:', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'أساسي', 60),
    ('3-1-1-1', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 3-1-1-1', 'إجراء المسح الأمني (Screening and Vetting) لموظفي الأطراف الخارجية الذين لديهم صلاحيات الاطلاع على البيانات.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'فرعي', 61),
    ('3-1-1-2', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 3-1-1-2', 'وجود ضمانات تعاقدية للقدرة على حذف بيانات الجهة بطرق آمنة لدى الطرف الخارجي عند الانتهاء/إنهاء العلاقة التعاقدية مع تقديم الأدلة على ذلك.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'فرعي', 62),
    ('3-1-1-3', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 3-1-1-3', 'توثيق كافة عمليات مشاركة البيانات مع الأطراف الخارجية، على أن يشمل ذلك مبررات مشاركة البيانات.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'فرعي', 63),
    ('3-1-1-4', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 3-1-1-4', 'عند مشاركة البيانات خارج المملكة يجب التحقق من قدرة الجهة المستضيفة على حماية تلك البيانات والحصول على موافقة صاحب الصلاحية بالإضافة إلى الالتزام بالمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'فرعي', 64),
    ('3-1-1-5', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 3-1-1-5', 'إلزام الأطراف الخارجية بإبلاغ الجهة مباشرةً عند حدوث حادثة أمن سيبراني قد تؤثر على البيانات التي تمت مشاركتها أو إنشائها.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'فرعي', 65),
    ('3-1-1-6', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 3-1-1-6', 'إعادة تصنيف البيانات إلى أقل مستوى يحقق الهدف، قبل مشاركتها مع الأطراف الخارجية وذلك باستخدام تقنيات تعتيم البيانات (Data Masking) أو تقنيات مزج البيانات (Data Scrambling).', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'فرعي', 66),
    ('3-1-2', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 3-1-2', 'بما يتوافق مع المتطلبات التشريعية والتنظيمية ذات العلاقة، وبالإضافة إلى ما ينطبق من الضوابط الأساسية للأمن السيبراني والضوابط ضمن المكونات الرئيسية رقم (١) و (٢) و (٣) من هذه الوثيقة، يجب أن تغطي متطلبات الأمن السيبراني عند التعامل مع الجهات الاستشارية للمشاريع الاستراتيجية ذات الحساسية العالية على المستوى الوطني بحد أدنى، ما يلي:', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'أساسي', 67),
    ('3-1-2-1', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 3-1-2-1', 'إجراء المسح الأمني (Screening or Vetting) لموظفي شركات الخدمات الاستشارية الذين لديهم صلاحيات الاطلاع على البيانات.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'فرعي', 68),
    ('3-1-2-2', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 3-1-2-2', 'وجود ضمانات تعاقدية تشمل إلزام موظفي الخدمات الاستشارية بعدم إفشاء المعلومات وكذلك القدرة على حذف بيانات الجهة بطرق آمنة لدى شركات الخدمات الاستشارية عند الانتهاء/إنهاء العلاقة التعاقدية مع تقديم الأدلة على ذلك.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'فرعي', 69),
    ('3-1-2-3', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 3-1-2-3', 'توثيق كافة عمليات مشاركة البيانات مع شركات الخدمات الاستشارية، على أن يشمل ذلك مبررات مشاركة البيانات.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'فرعي', 70),
    ('3-1-2-4', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 3-1-2-4', 'إلزام شركات الخدمات الاستشارية بإبلاغ الجهة مباشرةً عند حدوث حادثة أمن سيبراني قد تؤثر على البيانات التي تمت مشاركتها أو إنشائها.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'فرعي', 71),
    ('3-1-2-5', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 3-1-2-5', 'إعادة تصنيف البيانات إلى أقل مستوى يحقق الهدف، قبل مشاركتها مع شركات الخدمات الاستشارية وذلك باستخدام تقنيات تعتيم البيانات (Data Masking) أو تقنيات مزج البيانات (Data Scrambling).', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'فرعي', 72),
    ('3-1-2-6', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 3-1-2-6', 'تخصيص قاعة مغلقة لموظفي شركات الخدمات الاستشارية لأداء أعمالهم، مع توفير أجهزة مخصصة مملوكة للجهة يتم من خلالها مشاركة البيانات ومعالجتها.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'فرعي', 73),
    ('3-1-2-7', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 3-1-2-7', 'تفعيل أنظمة التحكم بالدخول والخروج من القاعة المغلقة، على أن يكون للمصرح لهم فقط.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'فرعي', 74),
    ('3-1-2-8', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 3-1-2-8', 'منع خروج الأجهزة ووحدات التخزين والوثائق من القاعة المغلقة، ومنع إدخال أي أجهزة إلكترونية للقاعة.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'فرعي', 75)
), framework as (select id from public.frameworks where code='DCC')
insert into public.controls(framework_id,control_code,title_ar,description_ar,domain_ar,implementation_status,evidence_status,verification_status)
select framework.id,source.control_code,source.title_ar,source.description_ar,source.domain_ar,'not_started','not_uploaded','not_verified' from source cross join framework
on conflict (framework_id,control_code) do update set title_ar=excluded.title_ar,description_ar=excluded.description_ar,domain_ar=excluded.domain_ar;
